-- Telugu and Hindi rows for the 12 reels (data/reels.json): translated captions over the
-- English clip (`file` stays <id>.en.mp4) and the English title, which quiz questions quote.
on conflict (id, language) do update set
  file = excluded.file, title = excluded.title, captions = excluded.captions, pillar = excluded.pillar,
  tags = excluded.tags, level = excluded.level, chapter = excluded.chapter;
