insert into reels_items (id, language, file, title, captions, pillar, tags, level, chapter, created_at) values
  ('budget-needs-vs-wants', 'te', 'budget-needs-vs-wants.en.mp4', 'Peter Learns Needs vs Wants', 'ముందు అవసరాలు. మిగిలినదే కోరికలకు.', 'budget', array['needs-vs-wants', 'pocket-money'], 2, 'budget-needs-vs-wants', '2026-10-11T00:00:00Z'),
  ('budget-50-30-20', 'te', 'budget-50-30-20.en.mp4', 'Stewie Explains the 50-30-20 Rule', 'బడ్జెట్ అనేది ఒక పంజరం కాదు. అది మీకు నిజంగా ఏమి కావాలో దాని కోసం వేసుకునే ఒక ప్రణాళిక.', 'budget', array['50-30-20', 'pocket-money'], 14, 'budget-pocket-money-plan', '2026-10-11T00:00:00Z'),
  ('budget-no-cost-emi', 'te', 'budget-no-cost-emi.en.mp4', 'Peter Falls for "No-Cost EMI"', 'మీరు దాన్ని రెండుసార్లు భరించలేకపోతే, EMIలో కూడా భరించలేరు.', 'budget', array['bills-and-emi'], 18, null, '2026-10-11T00:00:00Z'),
  ('budget-chai-math', 'te', 'budget-chai-math.en.mp4', 'Peter''s Chai Math', 'చిన్న లీకులు పెద్ద ఓడలను ముంచుతాయి. ముందు పొదుపు చేయండి, మిగిలినది ఖర్చు పెట్టండి.', 'budget', array['tracking-spending'], 8, 'budget-pocket-money-plan', '2026-10-11T00:00:00Z'),
  ('save-emergency-fund', 'te', 'save-emergency-fund.en.mp4', 'Peter Breaks His Phone', 'మీరు అత్యవసర పరిస్థితులను ఊహించలేరు. వాటికి సిద్ధంగా ఉండగలరు.', 'save', array['emergency-fund'], 6, 'save-emergency-fund', '2026-10-11T00:00:00Z'),
  ('budget-minimum-due', 'te', 'budget-minimum-due.en.mp4', 'Peter Pays the "Minimum Due"', 'కనీస చెల్లింపు = గరిష్ట నష్టం. పూర్తి మొత్తాన్ని చెల్లించండి.', 'budget', array['bills-and-emi', 'compound-interest'], 26, null, '2026-10-11T00:00:00Z'),
  ('save-compounding', 'te', 'save-compounding.en.mp4', 'Rick Explains Compounding', 'ఎక్కువ కాలం > సరైన సమయం. ముందుగానే మొదలుపెట్టండి.', 'save', array['compound-interest', 'time-horizon'], 30, 'save-magic-of-compounding', '2026-10-11T00:00:00Z'),
  ('invest-risk-and-diversification', 'te', 'invest-risk-and-diversification.en.mp4', 'Rick Explains Risk & Diversification', 'మీ గుడ్లన్నీ ఒకే బుట్టలో పెట్టవద్దు.', 'invest', array['risk-and-return', 'diversification'], 50, 'invest-risk-and-return', '2026-10-11T00:00:00Z'),
  ('save-inflation', 'te', 'save-inflation.en.mp4', 'Rick Explains Inflation', 'కదలకుండా ఉన్న డబ్బు నెమ్మదిగా విలువను కోల్పోతుంది.', 'save', array['inflation'], 34, 'save-magic-of-compounding', '2026-10-11T00:00:00Z'),
  ('safety-never-share-otp', 'te', 'safety-never-share-otp.en.mp4', 'Morty Almost Shares His OTP', 'మీ OTP మీ ఇంటి తాళం చెవి లాంటిది. దాన్ని ఎప్పుడూ ఇతరులకు ఇవ్వకండి.', 'safety', array['otp-and-pin', 'upi-fraud'], 1, 'safety-upi-and-otp', '2026-10-11T00:00:00Z'),
  ('safety-spot-the-scam', 'te', 'safety-spot-the-scam.en.mp4', 'Spot the Scam with Rick', 'తొందర + హామీ + ముందే డబ్బు = మోసం.', 'safety', array['phishing', 'fake-loan-apps', 'ponzi-and-chit-scams'], 12, 'safety-spot-the-scam', '2026-10-11T00:00:00Z'),
  ('safety-money-mule', 'te', 'safety-money-mule.en.mp4', 'Morty Becomes a Money Mule', 'మీ ఖాతాను ఉపయోగించుకోవడానికి వాళ్ళు మీకు డబ్బు చెల్లిస్తే, దొరికిపోయేది మీరే.', 'safety', array['upi-fraud'], 22, 'safety-spot-the-scam', '2026-10-11T00:00:00Z'),
  ('budget-needs-vs-wants', 'hi', 'budget-needs-vs-wants.en.mp4', 'Peter Learns Needs vs Wants', 'ज़रूरतें पहले। जो बचे, वह चाहतों के लिए।', 'budget', array['needs-vs-wants', 'pocket-money'], 2, 'budget-needs-vs-wants', '2026-10-11T00:00:00Z'),
  ('budget-50-30-20', 'hi', 'budget-50-30-20.en.mp4', 'Stewie Explains the 50-30-20 Rule', 'बजट कोई पिंजरा नहीं है। यह उस चीज़ की योजना है जो आप सच में चाहते हैं।', 'budget', array['50-30-20', 'pocket-money'], 14, 'budget-pocket-money-plan', '2026-10-11T00:00:00Z'),
  ('budget-no-cost-emi', 'hi', 'budget-no-cost-emi.en.mp4', 'Peter Falls for "No-Cost EMI"', 'अगर आप इसे दो बार नहीं ख़रीद सकते, तो EMI पर भी नहीं ख़रीद सकते।', 'budget', array['bills-and-emi'], 18, null, '2026-10-11T00:00:00Z'),
  ('budget-chai-math', 'hi', 'budget-chai-math.en.mp4', 'Peter''s Chai Math', 'छोटे-छोटे छेद बड़े जहाज़ डुबो देते हैं। पहले बचत करें, फिर जो बचे उसे ख़र्च करें।', 'budget', array['tracking-spending'], 8, 'budget-pocket-money-plan', '2026-10-11T00:00:00Z'),
  ('save-emergency-fund', 'hi', 'save-emergency-fund.en.mp4', 'Peter Breaks His Phone', 'आप आपात स्थितियों का अनुमान नहीं लगा सकते। आप उनके लिए तैयार रह सकते हैं।', 'save', array['emergency-fund'], 6, 'save-emergency-fund', '2026-10-11T00:00:00Z'),
  ('budget-minimum-due', 'hi', 'budget-minimum-due.en.mp4', 'Peter Pays the "Minimum Due"', 'न्यूनतम देय राशि = अधिकतम कष्ट। पूरा भुगतान करें।', 'budget', array['bills-and-emi', 'compound-interest'], 26, null, '2026-10-11T00:00:00Z'),
  ('save-compounding', 'hi', 'save-compounding.en.mp4', 'Rick Explains Compounding', 'लंबा समय > सही समय। जल्दी शुरू करें।', 'save', array['compound-interest', 'time-horizon'], 30, 'save-magic-of-compounding', '2026-10-11T00:00:00Z'),
  ('invest-risk-and-diversification', 'hi', 'invest-risk-and-diversification.en.mp4', 'Rick Explains Risk & Diversification', 'अपने सारे अंडे एक ही टोकरी में मत रखो।', 'invest', array['risk-and-return', 'diversification'], 50, 'invest-risk-and-return', '2026-10-11T00:00:00Z'),
  ('save-inflation', 'hi', 'save-inflation.en.mp4', 'Rick Explains Inflation', 'जो पैसा स्थिर पड़ा रहता है, वह धीरे-धीरे अपना मूल्य खो देता है।', 'save', array['inflation'], 34, 'save-magic-of-compounding', '2026-10-11T00:00:00Z'),
  ('safety-never-share-otp', 'hi', 'safety-never-share-otp.en.mp4', 'Morty Almost Shares His OTP', 'आपका ओटीपी आपके घर की चाबी है। इसे कभी किसी को न दें।', 'safety', array['otp-and-pin', 'upi-fraud'], 1, 'safety-upi-and-otp', '2026-10-11T00:00:00Z'),
  ('safety-spot-the-scam', 'hi', 'safety-spot-the-scam.en.mp4', 'Spot the Scam with Rick', 'जल्दबाज़ी + गारंटी + पहले भुगतान = धोखा।', 'safety', array['phishing', 'fake-loan-apps', 'ponzi-and-chit-scams'], 12, 'safety-spot-the-scam', '2026-10-11T00:00:00Z'),
  ('safety-money-mule', 'hi', 'safety-money-mule.en.mp4', 'Morty Becomes a Money Mule', 'अगर वे आपके खाते का उपयोग करने के लिए आपको भुगतान करते हैं, तो आप ही फंसेंगे।', 'safety', array['upi-fraud'], 22, 'safety-spot-the-scam', '2026-10-11T00:00:00Z')
